  const {
    CD,
    Ic,
    fmt
  } = window.CDOS;
  const KYC_BLUE = '#2B50E2'; // brand accent for recommendations / selection
  const TIER_META = {
    quick: {
      tag: 'Keeps files current',
      best: 'walk-ins & already-verified clients'
    },
    verify: {
      tag: 'The standard',
      best: 'every first-time client'
    },
    plus: {
      tag: 'Most protection',
      best: 'large deals & high-risk profiles'
    }
  };
  const Portal = ({
    children
  }) => ReactDOM.createPortal(children, document.body);
  const KKEY = 'cdos_kyc_v1';
  const HKEY = 'cdos_report_history_v1';
  const PKEY = 'cdos_kyc_provider';
  // The verification provider is swappable — defaults to Persona, set from Settings.
  let PROVIDER = (() => {
    try {
      return localStorage.getItem(PKEY) || 'Persona';
    } catch (e) {
      return 'Persona';
    }
  })();
  // Buried “partner authorization code” → lifetime margin adjustment on every check.
  // Sold to founding desks as a perk; stored quietly, applied to all KYC pricing.
  const RKEY = 'cdos_kyc_partner_rate';
  const PARTNER_CODES = {
    'YFX-FOUNDER': 0.10,
    'YFX-PARTNER': 0.07,
    'YFX-INTRO': 0.05
  };
  let RATE_ADJ = (() => {
    try {
      return Math.min(0.5, Math.max(0, +localStorage.getItem(RKEY) || 0));
    } catch (e) {
      return 0;
    }
  })();
