    const adj = PARTNER_CODES[String(code || '').trim().toUpperCase()];
    if (adj == null) return {
      ok: false
    };
    RATE_ADJ = adj;
    try {
      localStorage.setItem(RKEY, String(adj));
    } catch (e) {}
